{"cards": [{"node_code": "N_2e3d2409ec971f6e", "definition": "研究以消除浪费、提升流动效率为核心的精益生产体系，涵盖价值流分析、标准作业、快速换型、现场管理及约束理论与持续改进方法。", "boundary": "聚焦于生产流程的优化逻辑与管理哲学，强调通过标准化、可视化和消除非增值活动来提升系统效率。边界在于关注流程层面的改进策略与工具应用，不涉及具体的工艺参数优化、设备硬件设计或纯财务成本核算。", "includes": ["价值流图（VSM）、节拍时间（Takt Time）及连续流设计", "标准作业组合、快速换型（SMED）、5S现场管理及看板拉动系统", "约束理论（TOC）应用、PDCA循环及持续改进（Kaizen）机制"], "excludes": ["具体的机械加工工艺参数优化或刀具材料选择", "独立的财务成本估算模型或纯会计制度研究"], "sibling_distinctions": [{"other_code": "N_bdeaac7e86fa8358", "rule": "本节点关注宏观流程优化与消除浪费的系统方法；兄弟节点关注微观作业层面的动作分析、时间测定及工时定额制定。"}, {"other_code": "N_4100749d5498b1d2", "rule": "本节点关注通过流程改进提升效率的管理手段；兄弟节点关注改进后的成本核算、生产率指标量化及运营绩效评估。"}, {"other_code": "N_9d3e59cf97757906", "rule": "本节点关注基于拉动和流动的生产组织方式；兄弟节点关注具体的生产计划编制、作业排序算法及调度控制。"}], "cross_boundary_rule": "涉及生产改进的研究，若侧重消除浪费的流程重构与管理工具（如VSM、SMED），主挂载本节点；若侧重具体的工时测定方法或动作分析技术，主挂载“工作研究、动作时间与作业测定”；若侧重改进后的成本效益量化分析，主挂载“制造成本、生产率与运营绩效”。"}, {"node_code": "N_bdeaac7e86fa8358", "definition": "研究通过科学方法分析作业动作、测定标准时间、确定工作单元及负荷，以制定工时定额、优化作业流程并评估操作效率的基础技术。", "boundary": "聚焦于微观作业层面的时间-动作分析，包括动作研究、时间研究、操作记录及示迹分析。边界在于关注“人-机”交互中的基本动作单元及其时间消耗，不涉及宏观生产系统布局、整体流程优化策略或财务成本核算。", "includes": ["动作研究（如MTM、MODAPTS）、时间研究及标准时间制定", "工作单元划分、宽放（津贴）系数确定及作业负荷平衡", "操作记录（Operation Record）、示迹（Motion Study）及作业分析方法"], "excludes": ["宏观生产计划调度、车间布局或供应链物流管理", "具体的机械加工工艺原理、设备选型或自动化控制算法"], "sibling_distinctions": [{"other_code": "N_2e3d2409ec971f6e", "rule": "本节点关注微观动作与时间的科学测定及定额制定；兄弟节点关注宏观流程的浪费消除、价值流优化及持续改进体系。"}, {"other_code": "N_4100749d5498b1d2", "rule": "本节点关注工时定额的制定方法与作业效率分析；兄弟节点关注基于工时数据的成本估算、生产率指标计算及运营绩效评估。"}, {"other_code": "N_9d3e59cf97757906", "rule": "本节点关注单个作业或工序的时间标准与动作优化；兄弟节点关注多工序、多资源的生产计划编制与作业调度排序。"}], "cross_boundary_rule": "涉及时间管理的研究，若侧重动作分解、时间测定技术及标准工时制定，主挂载本节点；若侧重基于标准工时的成本核算或绩效KPI计算，主挂载“制造成本、生产率与运营绩效”；若侧重利用标准工时进行整体生产排程，主挂载“生产计划、调度与控制”。"}, {"node_code": "N_4100749d5498b1d2", "definition": "研究制造过程中的成本构成、估算方法、生产率指标及运营绩效评估体系，旨在通过量化分析优化资源配置、控制成本并提升经济效益。", "boundary": "聚焦于制造运营的经济性分析，包括直接/间接成本、库存持有成本、产能利用率、OEE（设备综合效率）及投资回报率等指标。边界在于关注财务与运营数据的量化评估，不涉及具体的工艺改进技术、动作时间测定方法或生产调度算法实现。", "includes": ["劳动力成本、工时成本、材料成本及制造间接费用（Overhead）分析", "制造成本估算方法、作业成本法（ABC）及经济性分析", "生产率指标（如劳动生产率、设备利用率）、OEE及运营绩效仪表盘"], "excludes": ["具体的机械加工工艺优化、刀具寿命分析或设备硬件维护", "纯财务会计制度、税务筹划或企业整体战略管理"], "sibling_distinctions": [{"other_code": "N_2e3d2409ec971f6e", "rule": "本节点关注改进后的成本量化与绩效评估；兄弟节点关注导致效率提升的流程改进方法与管理工具。"}, {"other_code": "N_bdeaac7e86fa8358", "rule": "本节点关注基于工时数据的成本计算与效率指标；兄弟节点关注工时定额的测定方法、动作分析及标准时间制定。"}, {"other_code": "N_1c111ae16068ba42", "rule": "本节点关注库存持有成本及库存对绩效的影响；兄弟节点关注库存控制策略、补货模型及物流运作流程。"}], "cross_boundary_rule": "涉及运营指标的研究，若侧重成本估算、财务效益分析及KPI体系构建，主挂载本节点；若侧重通过精益工具降低浪费从而间接降低成本，主挂载“精益生产与运营改进”；若侧重库存水平的优化算法，主挂载“制造物流与库存”。"}]}
